INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CIV5_BC_FACTOID_TEXT','A resident of a distant orchard ward can name the Heart as their city without visiting its central square. Their immediate services belong to the ward, their standing belongs to the common charter, and their right of appeal travels with them.');
